export function createResearchWorkbench(sim,onEvent=()=>{}){
 const $=id=>document.getElementById(id);let worker=null,report=null;for(const link of document.querySelectorAll('.research-page-link'))link.addEventListener('click',()=>{try{localStorage.setItem('roadster-research-parameter-handoff',JSON.stringify({time:Date.now(),params:sim.params}));}catch{}});
 const explain={steer:'隔离平路：指定真实路轮转角阶跃，绕过道路限舵辅助，保留轮胎力与转向执行器。',rise:'普通 E 持续2秒后松开，目标上升率受限；不会请求原始80kN满阀。',hover:'10秒有限/恒压悬停，对照温压、喷流质量流率与失去支撑时刻。',roll:'从地面短脉冲起跳、完整滚转、按离地高度制导着陆，检查气量与接地速度。'};
 $('experiment-kind').onchange=()=>{const kind=$('experiment-kind').value;$('experiment-description').textContent=explain[kind];for(const id of ['experiment-speed','experiment-angle'])$(id).disabled=kind!=='steer';};$('experiment-kind').onchange();
 function draw(){if(!report||!report.rows.length)return;const c=$('experiment-chart'),g=c.getContext('2d'),w=c.width,h=c.height;g.fillStyle='#0e1d1e';g.fillRect(0,0,w,h);const key=report.kind==='steer'?'beta':'height',values=report.rows.map(r=>r[key]),lo=Math.min(0,...values),hi=Math.max(1,...values),span=hi-lo||1,left=48,right=w-20,top=20,bottom=h-35;g.font='14px Consolas';for(let i=0;i<5;i++){const y=top+(bottom-top)*i/4;g.strokeStyle='#294044';g.beginPath();g.moveTo(left,y);g.lineTo(right,y);g.stroke();g.fillStyle='#a6b8b8';g.fillText((hi-span*i/4).toFixed(1),4,y+4);}g.strokeStyle='#c8e6bd';g.lineWidth=2;g.beginPath();report.rows.forEach((r,i)=>{const x=left+r.time/report.input.duration*(right-left),y=bottom-(r[key]-lo)/span*(bottom-top);i?g.lineTo(x,y):g.moveTo(x,y);});g.stroke();g.fillStyle='#b8c7c8';g.fillText(key==='beta'?'质心侧偏 / °':'重心高度 / m',left,h-9);g.fillText(report.input.duration+' s',right-42,h-9);}
 function download(data,name,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 $('experiment-run').onclick=()=>{worker?.terminate();worker=new Worker('./experiment-worker.js',{type:'module'});$('experiment-run').disabled=true;$('experiment-status').textContent='计算中：120Hz物理，20Hz记录…';const request={kind:$('experiment-kind').value,params:{...sim.params},speedKmh:+$('experiment-speed').value,angleDeg:+$('experiment-angle').value};onEvent('batch_experiment',request);worker.onmessage=e=>{$('experiment-run').disabled=false;worker.terminate();worker=null;if(!e.data.ok){$('experiment-status').textContent=e.data.error;return;}report=e.data.report;const m=report.metrics;const metrics=[];
 if(report.kind==='steer')metrics.push(`最大质心侧偏　${(m.maxBetaDeg===null?'N/A':m.maxBetaDeg.toFixed(2))} °`,`最大偏航速率　${m.maxYawRateDegS.toFixed(2)} °/s`);
 else metrics.push(`上升速率峰值　${m.maxVerticalMps.toFixed(2)} m/s`,`最高重心高度　${m.maxHeightM.toFixed(2)} m`);
 if(report.kind==='roll')metrics.push('完整倒置　'+(m.inverted?'已达到':'未达到'));
 metrics.push(`耗气 / 剩气　${m.gasUsedKg.toFixed(2)} / ${m.remainingGasKg.toFixed(2)} kg`);
 if(report.kind==='hover')metrics.push(m.lossOfSupportSeconds!==null?`支撑裕度不足　${m.lossOfSupportSeconds.toFixed(2)} s`:'试验窗口内仍有支撑裕度');
 if(m.touchdown)metrics.push(`首次接地垂速　${m.touchdown.speedMps.toFixed(3)} m/s`);
 $('experiment-results').textContent=metrics.join('\n');$('experiment-status').textContent=`${report.outcome==='rejected'?'预检拒绝':'计算完成'} · ${report.rows.length}个20Hz样本 · 独立试验台`;$('experiment-json').disabled=false;$('experiment-csv').disabled=false;draw();$('experiment-chart').dataset.result=JSON.stringify({modelVersion:report.modelVersion,kind:report.kind,metrics:report.metrics,samples:report.rows.length});};worker.onerror=e=>{$('experiment-run').disabled=false;$('experiment-status').textContent='试验中断：'+e.message;worker?.terminate();};worker.postMessage(request);};
 $('experiment-cancel').onclick=()=>{worker?.terminate();worker=null;$('experiment-run').disabled=false;$('experiment-status').textContent='已停止独立试验，当前车辆状态保留。';};
 $('experiment-json').onclick=()=>report&&download(JSON.stringify(report,null,2),'roadster-'+report.kind+'-research.json','application/json');
 $('experiment-csv').onclick=()=>{if(!report)return;const keys=Object.keys(report.rows[0]);download('\uFEFF'+['# Model '+report.modelVersion,'# Params '+JSON.stringify(report.appliedParams),keys.join(','),...report.rows.map(r=>keys.map(k=>r[k]).join(','))].join('\r\n'),'roadster-'+report.kind+'-research.csv','text/csv;charset=utf-8');};
 return{get report(){return report;}};
}
